#[cfg(test)] mod review_meter {
 use super::*; use crate::executor_allocation_meter as m;
 #[test] fn parser() {
  let pool=Budget::new(64*1024*1024,0); let denied=Budget::new(0,0);
  let mut bytes=Vec::new(); for _ in 0..1000 {bytes.extend_from_slice(b" M ");bytes.extend(std::iter::repeat_n(0xff,1024));bytes.push(0);}
  let _=std::thread::current();let _=pool.snapshot();let _=denied.snapshot();
  m::start();let parsed=parse_status_in(&bytes,1000,&pool).unwrap();let c=m::peek();let held=pool.snapshot().used;let peak=pool.snapshot().peak;
  assert!(c.live>=0 && c.live as usize<=held);assert!(c.peak as usize<=peak);drop(parsed);let final_c=m::stop();assert_eq!(final_c.live,0);assert_eq!(pool.snapshot().used,0);
  m::start();assert!(matches!(parse_status_in(&bytes,1000,&denied),Err(Error::Budget)));let refused=m::stop();assert_eq!(refused.allocations,0);
  eprintln!("REVIEW_ALLOC parser live={} peak={} held={} fee_peak={} denied_allocations=0 final=0",c.live,c.peak,held,peak);
 }
}

