#[cfg(all(test,unix))] mod review_meter {
 use super::*;use crate::executor_allocation_meter as m;
 #[test] fn pipes(){
  let pool=Budget::new(16*1024*1024,0);let cancel=Cancellation::try_new(&pool).unwrap();
  let command=||{let mut s=Spec::new("/bin/sh");s.args(["-c","head -c 1048576 /dev/zero; head -c 1048576 /dev/zero >&2; exec 1>&-; exec 2>&-; sleep 0.02"]);Ok(s)};
  {let warm=Cancellation::default();drop(run_split(command,&pool,Kind::Git,&warm,Duration::from_secs(5),[32768,4096]).unwrap());}let _=std::thread::current();
  m::start();let out=run_split(command,&pool,Kind::Git,&cancel,Duration::from_secs(5),[32768,4096]).unwrap();let c=m::peek();let held=pool.snapshot().used;let peak=pool.snapshot().peak;
  m::stop();drop(out);let after_output=m::peek();let caller_fee=pool.snapshot().used;drop(cancel);let after_caller=m::peek();
  eprintln!("REVIEW_TRACE live={} held={held} after_output={} caller_fee={caller_fee} after_caller={}",c.live,after_output.live,after_caller.live);
  assert!(after_output.live<=128,"lazy synchronization exceeds the caller token allowance");
  assert!(c.live>=0 && c.live as usize<=held,"live={} fee={held}",c.live);assert!(c.peak as usize<=peak);assert_eq!(after_caller.live,0);assert_eq!(pool.snapshot().used,0);assert_eq!(pool.snapshot().managed_workers,0);
  eprintln!("REVIEW_ALLOC pipes live={} peak={} held={} fee_peak={} final=0 workers=0",c.live,c.peak,held,peak);
 }
}

