  let _=std::fs::remove_dir_all(&path);std::fs::create_dir_all(&path).unwrap();for i in 0..2100 {std::fs::write(path.join(format!("f{i:05}.txt")),b"x").unwrap();}
  let cancel=Cancellation::default();let _=std::thread::current();let _=pool.snapshot();
  m::start();let plan=walk_in(&path,&cancel,&pool).unwrap();let c=m::peek();let held=pool.snapshot().used;let peak=pool.snapshot().peak;
